#!/usr/bin/env python3
from __future__ import annotations
import base64,gzip,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PAYLOAD=''
PACKAGE='# Cross-model Configurator Technical Data Migration\n\n## Package\n\n- Package ID: `cross_model_configurator_technical_data_migration_001`\n- Kind: `source_backed_technical_observation_migration`\n- Status: complete\n- Source date: 2026-08-04\n\n## Scope\n\nPersist the exact technical-data source lines from page 5 of all 18 registered official Dacia configurator PDFs.\n\n## Result\n\n- 18 exact configurator-code scopes;\n- 162 technical category blocks;\n- 349 preserved source lines;\n- no semantic key-value coercion;\n- no transfer across model family, phase, grade, powertrain, transmission or seat count.\n\n## Next package\n\n`cross_model_configurator_options_packages_accessories_migration_001` will capture the remaining option, package and accessory pages while preserving exact saved-state boundaries.\n'
TEST="import json\nimport unittest\nfrom pathlib import Path\nROOT=Path(__file__).resolve().parents[1]\nDATA=ROOT/'data/reporting/cross_model_configurator_technical_data.json'\nclass CrossModelConfiguratorTechnicalDataTest(unittest.TestCase):\n    def test_exact_technical_contract(self):\n        data=json.loads(DATA.read_text(encoding='utf-8'))\n        self.assertEqual(data['configuration_count'],18)\n        self.assertEqual(data['total_category_count'],162)\n        self.assertEqual(data['total_source_line_count'],349)\n        self.assertEqual(len({d['configuration_code'] for d in data['documents']}),18)\n        self.assertEqual(sum(d['source_line_count'] for d in data['documents']),349)\n        by_code={d['configuration_code']:d for d in data['documents']}\n        self.assertEqual(by_code['GGQ0LU']['source_line_count'],22)\n        self.assertEqual(by_code['MEOHF3']['source_line_count'],20)\n        self.assertEqual(by_code['ARKVJG']['source_line_count'],17)\n        self.assertEqual(data['normalization_status'],'source_lines_preserved; semantic key-value parsing deferred')\nif __name__=='__main__': unittest.main()\n"
def write(path,text):
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(text.rstrip()+"\n",encoding="utf-8",newline="\n")
def main():
    data=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)).decode('utf-8'))
    write(ROOT/'data/reporting/cross_model_configurator_technical_data.json',json.dumps(data,ensure_ascii=False,indent=2))
    lines=['# Cross-model Configurator Technical Data','',f"Observed: {data['observed_on']}",'',f"Configurations: {data['configuration_count']}",'',f"Technical category blocks: {data['total_category_count']}",'',f"Preserved source lines: {data['total_source_line_count']}",'']
    for doc in data['documents']:
        lines += [f"## {doc['configuration_code']} — {doc['filename']}",'']
        for cat in doc['categories']:
            lines.append(f"### {cat['category']}")
            lines.extend(f"- {line}" for line in cat['source_lines'])
            lines.append('')
    write(ROOT/'data/reporting/cross_model_configurator_technical_data.md','\n'.join(lines))
    write(ROOT/'project/packages/cross-model-configurator-technical-data-migration-20260805.md',PACKAGE)
    write(ROOT/'tests/test_cross_model_configurator_technical_data_20260805.py',TEST)
    p=ROOT/'project/state.json'; state=json.loads(p.read_text(encoding='utf-8'))
    if state['next_package']['package_id']!='cross_model_configurator_technical_data_migration_001': raise RuntimeError('canonical next package changed')
    state['updated_on']='2026-08-05'; state['baseline']['tests']=1867
    state['current_package']={'package_id':'cross_model_configurator_technical_data_migration_001','kind':'source_backed_technical_observation_migration','name':'Cross-model Configurator Technical Data Migration','status':'complete','goal':'Persist exact page-5 technical-data source lines for all 18 saved configurator states without semantic coercion or cross-identity transfer.','manifest_paths':['data/reporting/cross_model_configurator_technical_data.json','data/reporting/cross_model_configurator_technical_data.md','project/STATE_SUMMARY.md','project/packages/cross-model-configurator-technical-data-migration-20260805.md','project/state.json','tests/test_cross_model_configurator_technical_data_20260805.py']}
    state['next_package']={'package_id':'cross_model_configurator_options_packages_accessories_migration_001','kind':'source_backed_option_package_accessory_migration','name':'Cross-model Configurator Options, Packages and Accessories Migration','status':'planned','goal':'Capture exact option, package and accessory source lines from the remaining pages of all 18 saved configurator PDFs while preserving exact saved-state boundaries.','manifest_paths':[]}
    write(p,json.dumps(state,ensure_ascii=False,indent=2))
if __name__=='__main__': main()
